10	/**
11	 * Rejects creating an owner when 100 or more owners have already been created today, counted by
12	 * {@link Owner#getRegistrationDate()} against the server's current date. The owner being created is
13	 * not yet persisted, so it is not part of the count.
14	 */
15	public class EnsureDailyOwnerLimit {
16	
17	    private static final int MAX_OWNERS_PER_DAY = 100;
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
20	            throws DailyOwnerLimitException {
21	        LocalDate today = LocalDate.now();
22	        long count = ownerRepository.findAll().stream()
23	                .filter(existing -> !existing.getId().equals(owner.getId()))
24	                .filter(existing -> today.equals(existing.getRegistrationDate()))
25	                .count();
26	        if (count >= MAX_OWNERS_PER_DAY) {
27	            throw new DailyOwnerLimitException(
28	                    MAX_OWNERS_PER_DAY + " or more owners have already been created today");
29	        }
30	    }
31	}
