7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where
9	 * CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
10	 * three letters of the last name and NNNN a per-city 4-digit zero-padded sequence equal to
11	 * one more than the number of owners already in that city.
12	 */
13	public class AssignCustomerCode {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String city = owner.getCity();
17	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
18	        String lastName = owner.getLastName();
19	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
20	        long sequence = ownerRepository.findAll().stream()
21	                .filter(existing -> !existing.getId().equals(owner.getId()))
22	                .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
23	                .count() + 1;
24	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
25	    }
26	}
